#include "rom_kernel.h"
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#define A(x) (TF_RAM_BASE+UINT32_C(x))
static tf_model memory;static rc_adapter candidate;static rk_model kernel;
static uint8_t runtime[76800];static unsigned checks,failures,groups,handler_calls,radio_calls,one_calls;
static uint32_t irq,raw_clock;static int mutate_cursor,return_unknown,skip_copy;
#define CHECK(x) do{checks++;if(!(x)){failures++;printf("FAIL line=%d %s\n",__LINE__,#x);}}while(0)
static void group(const char *s){groups++;printf("GROUP %s\n",s);}
static void put(uint32_t a,uint32_t v,unsigned n){unsigned i;for(i=0;i<n;i++){memory.ram[a-TF_RAM_BASE+i]=(uint8_t)(v>>(i*8));memory.known[a-TF_RAM_BASE+i]=255;}}
static uint32_t get(uint32_t a,unsigned n){unsigned i;uint32_t v=0;for(i=0;i<n;i++)v|=(uint32_t)memory.ram[a-TF_RAM_BASE+i]<<(i*8);return v;}
static int clock_read(void *p,uint32_t token,uint32_t *v){(void)p;CHECK(token==0x18f1a);*v=raw_clock;return 1;}
static int status(void *p,rc_adapter *a,unsigned c,uint32_t d){(void)p;(void)a;(void)c;(void)d;return 1;}
static rk_flow invoke(void *p,rk_model *m,const rk_request *r,rk_result *out){(void)p;CHECK(m==&kernel);out->known=UINT32_MAX;out->value=0;
    if(r->kind==RK_MMIO_READ){CHECK(r->target==0x4002420c&&r->width==4);out->value=irq;return RK_RETURNED;}
    if(r->kind==RK_MMIO_WRITE){CHECK(r->target==0x4002420c&&r->width==4&&r->count==1);irq=r->arguments[0];return RK_RETURNED;}
    if(r->kind==RK_FENCE_I)return RK_RETURNED;
    if(r->kind==RK_TASK_HANDLER){handler_calls++;CHECK(r->count==2);if(return_unknown){out->known=0;return RK_RETURNED;}if(mutate_cursor){put(A(0x304c),4,1);put(A(0x308c),2,2);put(get(A(0x3094),4)+8,8,2);out->value=3;}else out->value=r->arguments[1]&~1u;return RK_RETURNED;}
    if(r->kind==RK_NATIVE_CALL){if(r->target==0x2222){one_calls++;put(A(0x3078),0x3333,4);return RK_RETURNED;}if(r->target==0x200024c6||r->target==0x6666||r->target==0x7777||r->target==0x2000061a){radio_calls++;return RK_RETURNED;}if(r->target==0x9999){one_calls++;CHECK(r->arguments[0]==0xabcdef);if(!skip_copy)put(get(A(0x30dc),4)+8,1,4);return RK_RETURNED;}}
    return RK_HALT;
}
static void fresh(void){rc_hooks hooks;rk_backend b;uint32_t s=9;uint8_t t=255;memset(&memory,0,sizeof(memory));memset(memory.known,255,sizeof(memory.known));memset(&hooks,0,sizeof(hooks));hooks.clock=clock_read;hooks.status=status;memory.runtime=runtime;memory.runtime_length=sizeof(runtime);raw_clock=0;irq=0x12345678;handler_calls=radio_calls=one_calls=0;mutate_cursor=return_unknown=skip_copy=0;CHECK(rc_attach(&candidate,&memory,RC_WCH_64BE955_V130,&hooks)==1);CHECK(rc_prepare(&candidate,A(0x418c),0x7000,14)==1);CHECK(rc_task_register(&candidate,0x9003,&t)==1&&t==3);CHECK(rc_task_register(&candidate,0x9004,&t)==1&&t==4);CHECK(rc_clock_init(&candidate,0x18f1a,UINT32_MAX,16000,1000,1,&s)==1&&s==0);b.context=NULL;b.invoke=invoke;CHECK(rk_attach(&kernel,&candidate,&b)==1);put(A(0x3048),0,4);}
static uint32_t message(unsigned n){uint32_t p=0;CHECK(rc_msg_allocate(&candidate,(uint16_t)n,&p)==1&&p!=0);return p;}
static uint32_t pending(unsigned task){return get(A(0x3094),4)+2u*task;}
static void queues(void){uint32_t a,b,c,p=0,s=9;group("native global queue owns per-task messages and preserves other task event");fresh();a=message(4);b=message(4);c=message(4);CHECK(rk_msg_send(&kernel,3,a,&s)==RK_RETURNED&&s==0);CHECK(rk_msg_send(&kernel,4,b,&s)==RK_RETURNED&&s==0);CHECK(rk_msg_send(&kernel,3,c,&s)==RK_RETURNED&&s==0);CHECK(get(A(0x3048),4)==a);CHECK(get(a-8,4)==b&&get(b-8,4)==c);CHECK(get(a-2,1)==3&&get(b-2,1)==4);CHECK(get(pending(3),2)==0x8000&&get(pending(4),2)==0x8000);CHECK(irq==0x12345678);CHECK(rk_msg_receive(&kernel,3,&p)==RK_RETURNED&&p==a);CHECK(get(A(0x3048),4)==b&&get(b-8,4)==c);CHECK(get(a-8,4)==0&&get(a-2,1)==255);CHECK(get(pending(3),2)==0x8000);CHECK(rk_msg_receive(&kernel,3,&p)==RK_RETURNED&&p==c);CHECK(get(b-8,4)==0);CHECK(get(pending(3),2)==0);CHECK(get(pending(4),2)==0x8000);CHECK(rk_msg_receive(&kernel,4,&p)==RK_RETURNED&&p==b);CHECK(get(A(0x3048),4)==0);CHECK(rk_msg_receive(&kernel,3,&p)==RK_RETURNED&&p==0);CHECK(irq==0x12345678);}
static void send_gates(void){uint32_t p,s=99,before,after;group("raw task gate, invalid-header deallocation status ignored, NULL5 and queue reset no free");fresh();CHECK(rk_msg_send(&kernel,3,0,&s)==RK_RETURNED&&s==5);p=message(4);CHECK(rc_heap_free_sum(&candidate,&before)==1);CHECK(rk_msg_send_register(&kernel,0x103,p,&s)==RK_RETURNED&&s==3);CHECK(rc_heap_free_sum(&candidate,&after)==1&&after>before);fresh();p=message(4);put(p-2,3,1);CHECK(rk_msg_send(&kernel,3,p,&s)==RK_RETURNED&&s==5);CHECK(get(p-2,1)==3);CHECK(get(A(0x3048),4)==0);fresh();p=message(4);CHECK(rk_msg_send(&kernel,3,p,&s)==RK_RETURNED&&s==0);CHECK(rk_queue_reset(&kernel)==RK_RETURNED);CHECK(get(A(0x3048),4)==0&&get(p-2,1)==3);CHECK(get(pending(3),2)==0x8000);}
static void queue_boundaries(void){uint32_t p,s=91;group("missing MMIO and unknown owner halt at literal prefix, no fake IRQ restore");fresh();p=message(4);kernel.backend.invoke=NULL;CHECK(rk_msg_send(&kernel,3,p,&s)==RK_HALT);CHECK(s==91&&get(A(0x3048),4)==0);fresh();p=message(4);memory.known[p-TF_RAM_BASE-2]=0;CHECK(rk_msg_send(&kernel,3,p,&s)==RK_HALT);CHECK(irq==0);CHECK(get(A(0x3048),4)==0);CHECK(kernel.unknown_address==p-2);}
static void task_scan(void){uint32_t p;group("task scan cursor, posted/suppressed masks and one-shot pointer reread");fresh();put(A(0x304c),3,1);put(pending(3),3,2);CHECK(rk_system_process(&kernel)==RK_RETURNED);CHECK(handler_calls==1);CHECK(get(pending(3),2)==2);CHECK(get(A(0x304c),1)==4);fresh();mutate_cursor=1;put(A(0x304c),3,1);put(pending(3),3,2);put(A(0x3078),0x2222,4);CHECK(rk_system_process(&kernel)==RK_RETURNED);CHECK(handler_calls==1&&one_calls==1);CHECK(get(pending(3),2)==0);CHECK(get(pending(4),2)==9);CHECK(get(A(0x304c),1)==0);CHECK(get(A(0x3078),4)==0);fresh();put(A(0x304c),0,1);put(pending(0),1,2);p=get(A(0x3074),4);put(p,0x9000,4);CHECK(rk_system_process(&kernel)==RK_RETURNED);CHECK(handler_calls==1&&get(A(0x304c),1)==0);}
static void idle_gates(void){uint32_t node=0,s=0;group("no pending timer pump and idle/radio prelude must follow native gates");fresh();CHECK(rc_timer_start(&candidate,3,1,1,&s)==1&&s==1);raw_clock=10;CHECK(rk_system_process(&kernel)==RK_RETURNED);CHECK(rc_timer_find(&candidate,3,1,&node)==1&&node==0);CHECK(get(pending(3),2)==1);CHECK(handler_calls==0);fresh();put(A(0x30f0),0,1);put(A(0x33c9),1,1);put(A(0x33cb),6,1);put(A(0x3084),0x6666,4);CHECK(rk_system_process(&kernel)==RK_RETURNED);CHECK(get(A(0x33c9),1)==0&&radio_calls==2);fresh();put(A(0x30c4),1,4);CHECK(rk_system_process(&kernel)==RK_RETURNED);CHECK(radio_calls==1);fresh();put(A(0x30c4),1,4);put(A(0x341c),4,1);CHECK(rk_system_process(&kernel)==RK_RETURNED);CHECK(radio_calls==0);}
static void handler_boundary(void){group("unknown handler result preserves cleared pending but stops before merge and cursor increment");fresh();return_unknown=1;put(A(0x304c),3,1);put(pending(3),7,2);CHECK(rk_system_process(&kernel)==RK_HALT);CHECK(handler_calls==1);CHECK(get(pending(3),2)==0);CHECK(get(A(0x304c),1)==3);CHECK(get(A(0x308c),2)==0);}
static void callback_alias(void){uint32_t meta;uint16_t out=0;group("internal callback nonzero task tests flag in task0 record, not selected record");fresh();meta=get(A(0x30dc),4);put(meta+16u*12u,0x9999,4);put(meta+16u*12u+4,0xabcdef,4);put(meta+16u*12u+8,0,4);CHECK(rk_internal_dispatch(&kernel,1,1,&out)==RK_RETURNED&&out==0);CHECK(one_calls==1);CHECK(get(meta+16u*12u,4)==0x9999);fresh();meta=get(A(0x30dc),4);put(meta+16u*12u,0x9999,4);put(meta+16u*12u+4,0xabcdef,4);skip_copy=1;CHECK(rk_internal_dispatch(&kernel,1,1,&out)==RK_RETURNED&&out==0);CHECK(get(meta+16u*12u,4)==0&&get(meta+16u*12u+4,4)==0);}
static void profile_boundary(void){group("candidate fault is a call boundary, not a successful kernel return");fresh();put(A(0x3048),0x1234,4);candidate.fault=1;candidate.last_unknown_va=0x43094;candidate.last_unknown_address=A(0x4321);CHECK(rk_queue_reset(&kernel)==RK_HALT);CHECK(get(A(0x3048),4)==0x1234);CHECK(kernel.unknown_address==A(0x4321));}
static void internal_messages(void){uint32_t p,meta,before,after;uint16_t out=99;group("internal1/2 message bit priority and unconditional callback clear differ from internal0");fresh();p=message(4);put(p-2,1,1);put(A(0x3048),p,4);put(pending(1),0x8001,2);CHECK(rc_heap_free_sum(&candidate,&before)==1);CHECK(rk_internal_message_dispatch(&kernel,1,0x8001,&out)==RK_RETURNED&&out==1);CHECK(get(A(0x3048),4)==0);CHECK(rc_heap_free_sum(&candidate,&after)==1&&after>before);CHECK(get(pending(1),2)==1);fresh();meta=get(A(0x30dc),4);put(meta+16u*12u,0x9999,4);put(meta+16u*12u+4,0xabcdef,4);put(meta+8,1,4);CHECK(rk_internal_message_dispatch(&kernel,1,1,&out)==RK_RETURNED&&out==0);CHECK(one_calls==1);CHECK(get(meta+16u*12u,4)==0&&get(meta+16u*12u+4,4)==0);}
int main(int argc,char **argv){FILE *f;if(argc!=2)return 2;f=fopen(argv[1],"rb");if(!f||fread(runtime,1,sizeof(runtime),f)!=sizeof(runtime)){if(f)fclose(f);return 2;}fclose(f);queues();send_gates();queue_boundaries();task_scan();idle_gates();handler_boundary();callback_alias();profile_boundary();internal_messages();printf("ROM_KERNEL_RESULT groups=%u checks=%u failures=%u original_executed=no hardware=no\n",groups,checks,failures);return failures?1:0;}
